interface Image { display(): void }
class RealImage implements Image {
  constructor(private url: string) {}
  display() { console.log('render', this.url) }
}
class ImageProxy implements Image {
  private real?: RealImage
  constructor(private url: string) {}
  display() { if (!this.real) this.real = new RealImage(this.url); this.real.display() }
}

interface DataService { fetch(id: string): Promise<string> }
class RemoteService implements DataService {
  async fetch(id: string) { return fetch(`/data/${id}`).then(r => r.text()) }
}
class CachingService implements DataService {
  private cache = new Map<string,string>()
  constructor(private real: DataService) {}
  async fetch(id: string) { if (this.cache.has(id)) return this.cache.get(id)!; const v = await this.real.fetch(id); this.cache.set(id, v); return v }
}

