interface OrderService { placeOrder(o:any): Promise<void> }
class RealOrderService implements OrderService { async placeOrder(o:any){ /* send to API */ } }
class OrderServiceProxy implements OrderService {
  constructor(private real: OrderService, private auth: any) {}
  async placeOrder(o:any){ if (!this.auth.canPlace(o.userId)) throw new Error('forbidden'); await this.real.placeOrder(o) }
}

// Version B
class SecureOrderService extends RealOrderService {
  constructor(private auth: any){ super() }
  async placeOrder(o:any){ if (!this.auth.canPlace(o.userId)) throw new Error('forbidden'); return super.placeOrder(o) }
}
